// ProtobufLexerInit initializes any static state used to implement ProtobufLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewProtobufLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func ProtobufLexerInit() {
	staticData := &ProtobufLexerLexerStaticData
	staticData.once.Do(protobuflexerLexerInit)
}

// NewProtobufLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewProtobufLexer(input antlr.CharStream) *ProtobufLexer {
	ProtobufLexerInit()
	l := new(ProtobufLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &ProtobufLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "Protobuf.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

